-- composition of rule kernels L:scalar_subquery_to_join x P:aggregate_statistics (datafusion), template product
SELECT count(*) FROM (SELECT '0'::text AS c0, 3 AS c1, GREATEST (1000::bigint, COALESCE (NULLIF (1000::bigint, (SELECT COUNT (*) FROM tl AS a2)), 1000::bigint)) AS c2, a1.c1 AS c3 FROM tp AS a1) AS ka CROSS JOIN (WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM cte1 AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END) AS kb;
-- pgfuzz:check kernel:product SELECT (SELECT count(*) FROM (SELECT '0'::text AS c0, 3 AS c1, GREATEST (1000::bigint, COALESCE (NULLIF (1000::bigint, (SELECT COUNT (*) FROM tl AS a2)), 1000::bigint)) AS c2, a1.c1 AS c3 FROM tp AS a1) AS ka) * (SELECT count(*) FROM (WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM cte1 AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END) AS kb)
